/* source: curated */
/* algorithm: rvv_k_reduce_n_lanes */
/* accuracy_class: bit_exact */
/* origin: generated by pipeline/generate_kernels.py via Codex (gpt-5.6-sol),
 *   first attempt, from the rvv_k_reduce_n_lanes seed in reference_kernels.py.
 *   Cross-compiled for rvv_x60 at generation time; NOT executed there.
 *   Numeric correctness is the on-board golden compare's job.
 *
 * WHY TWO PATHS. The two attention matmuls have opposite layouts and one loop
 * order is wrong for one of them:
 *
 *   transpose_b != 0  (Q.K^T)  b is [N,K], so a[i,:] and b[j,:] are BOTH
 *     K-contiguous. Reduce along K: vle8 both operands, vwmul into an i32m4
 *     accumulator, one vredsum per (i,j). Tail strips use _tu so lanes above
 *     vl keep the previous strip's partial sums, which is why the final
 *     reduction over vlmax is still correct when K is not a multiple of it.
 *
 *   transpose_b == 0  (.V, FFN)  b is [K,N], so b[k,j] at fixed j is strided
 *     by N. Reducing along K here would cost a strided load per element, so N
 *     goes in the lanes instead: hold an i32 accumulator over an N-strip and
 *     vwmul.vx it by the SCALAR a[i,k], with b[k,:] loaded contiguously.
 *
 * WHY THE REQUANTIZE TAIL IS SCALAR, in both paths. The oracle's tail is
 * roundf((float)acc * total). roundf is round-half-AWAY-FROM-ZERO; RVV float
 * conversion uses frm, normally round-to-nearest-EVEN. A vectorized tail
 * therefore disagrees on exact .5 cases and loses max_abs_err=0. It is O(M*N)
 * against an O(M*N*K) accumulation, so scalar costs almost nothing here.
 */


void kernel_matmul_s8(const int8_t *a, const int8_t *b, int8_t *output, int M, int K, int N, float scale_a, float scale_b, float scale_out, int transpose_b, float scale_div, int activation_min, int activation_max) {
    const float total = (scale_a * scale_b) / (scale_out * scale_div);

    if (M <= 0 || N <= 0) {
        return;
    }

    if (transpose_b) {
        const size_t vlmax = __riscv_vsetvlmax_e8m1();

        for (int i = 0; i < M; i++) {
            const int8_t *a_row = a + (size_t)i * (size_t)K;

            for (int j = 0; j < N; j++) {
                const int8_t *b_row = b + (size_t)j * (size_t)K;
                vint32m4_t vacc =
                    __riscv_vmv_v_x_i32m4(0, vlmax);
                int k = 0;

                while (k < K) {
                    size_t vl =
                        __riscv_vsetvl_e8m1((size_t)(K - k));
                    vint8m1_t va =
                        __riscv_vle8_v_i8m1(a_row + k, vl);
                    vint8m1_t vb =
                        __riscv_vle8_v_i8m1(b_row + k, vl);
                    vint16m2_t prod =
                        __riscv_vwmul_vv_i16m2(va, vb, vl);

                    vacc = __riscv_vwadd_wv_i32m4_tu(
                        vacc, vacc, prod, vl);
                    k += (int)vl;
                }

                vint32m1_t vinit =
                    __riscv_vmv_s_x_i32m1(0, 1);
                vint32m1_t vsum =
                    __riscv_vredsum_vs_i32m4_i32m1(
                        vacc, vinit, vlmax);
                int32_t acc =
                    __riscv_vmv_x_s_i32m1_i32(vsum);
                int32_t v =
                    (int32_t)roundf((float)acc * total);

                if (v < activation_min) {
                    v = activation_min;
                }
                if (v > activation_max) {
                    v = activation_max;
                }
                output[(size_t)i * (size_t)N + (size_t)j] =
                    (int8_t)v;
            }
        }
        return;
    }

    {
        const size_t vlmax = __riscv_vsetvlmax_e8m1();
        int32_t lane_acc[vlmax];

        for (int i = 0; i < M; i++) {
            const int8_t *a_row = a + (size_t)i * (size_t)K;
            int j0 = 0;

            while (j0 < N) {
                size_t vl =
                    __riscv_vsetvl_e8m1((size_t)(N - j0));
                vint32m4_t vacc =
                    __riscv_vmv_v_x_i32m4(0, vl);

                for (int k = 0; k < K; k++) {
                    vint8m1_t vb =
                        __riscv_vle8_v_i8m1(
                            b + (size_t)k * (size_t)N +
                                (size_t)j0,
                            vl);
                    vint16m2_t prod =
                        __riscv_vwmul_vx_i16m2(
                            vb, a_row[k], vl);
                    vacc = __riscv_vwadd_wv_i32m4(
                        vacc, prod, vl);
                }

                __riscv_vse32_v_i32m4(lane_acc, vacc, vl);

                for (size_t lane = 0; lane < vl; lane++) {
                    int32_t v = (int32_t)roundf(
                        (float)lane_acc[lane] * total);

                    if (v < activation_min) {
                        v = activation_min;
                    }
                    if (v > activation_max) {
                        v = activation_max;
                    }
                    output[(size_t)i * (size_t)N +
                           (size_t)j0 + lane] = (int8_t)v;
                }

                j0 += (int)vl;
            }
        }
    }
}
